css:
.glass-nav {
                background: rgba(0, 0, 0, 0.3);
                backdrop-filter: blur(20px);
                -webkit-backdrop-filter: blur(20px);
                border-bottom: 1px solid rgba(255, 255, 255, 0.1);
                transition: background 0.3s ease;
            }
.glass-nav.scrolled {
                background: rgba(0, 0, 0, 0.7);
            }
.hamburger-btn {
                display: none;
                background: rgba(255, 255, 255, 0.1);
                border: 1px solid rgba(255, 255, 255, 0.2);
                color: white;
                width: 40px;
                height: 40px;
                border-radius: 8px;
                cursor: pointer;
                font-size: 18px;
                transition: all 0.3s;
            }
.hamburger-btn:hover {
                background: rgba(255, 255, 255, 0.2);
            }
.mobile-menu {
                display: none;
                position: fixed;
                top: 0;
                left: 0;
                right: 0;
                bottom: 0;
                background: rgba(0, 0, 0, 0.95);
                backdrop-filter: blur(20px);
                -webkit-backdrop-filter: blur(20px);
                z-index: 100;
                flex-direction: column;
                align-items: center;
                justify-content: center;
                padding: 2rem;
            }
.mobile-menu.show {
                display: flex;
            }
.mobile-menu-item {
                color: white;
                font-size: 18px;
                font-weight: 600;
                padding: 15px 30px;
                text-decoration: none;
                text-align: center;
                width: 100%;
                max-width: 300px;
                border-bottom: 1px solid rgba(255, 255, 255, 0.2);
                transition: all 0.3s;
            }
.mobile-menu-item:hover {
                background: rgba(255, 255, 255, 0.1);
                color: #a78bfa;
            }
.close-menu-btn {
                position: absolute;
                top: 20px;
                right: 20px;
                background: rgba(255, 255, 255, 0.1);
                border: 1px solid rgba(255, 255, 255, 0.2);
                color: white;
                width: 44px;
                height: 44px;
                border-radius: 8px;
                cursor: pointer;
                font-size: 20px;
                transition: all 0.3s;
            }
